"use client";
import React, { useState, useEffect } from "react";
import { Settings, Users, Clock, Trophy, X, Zap } from "lucide-react";
import { initSocket } from "@/socket/socket";
import { createPortal } from "react-dom";

const SettingsScreen = ({ roomCode, playerId, hostId }) => {
  const socket = initSocket();
  const [settings, setSettings] = useState({
    maxPlayers: 8,
    roundDuration: 60,
    maxRounds: 3,
    difficulty: "easy",
  });
  const [showSettings, setShowSettings] = useState(false);
  const [animateSettings, setAnimateSettings] = useState(false);
  const [tempSettings, setTempSettings] = useState(settings);
  const [isHost, setIsHost] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    setIsHost(playerId === hostId);
  }, [playerId, hostId]);

  useEffect(() => {
    // Fetch current settings on mount
    if (socket && roomCode) {
      socket.emit("fetch-settings", { roomId: roomCode });
    }

    // Listen for settings updates
    const handleSettingsUpdated = (data) => {
      setSettings(data.settings);
      setTempSettings(data.settings);
      // Show notification if not the one who updated
      if (data.updatedBy) {
        // console.log(`Settings updated by ${data.updatedBy}`);
      }
    };

    const handleSettingsData = (data) => {
      setSettings(data.settings);
      setTempSettings(data.settings);
    };

    if (socket) {
      socket.on("settings-updated", handleSettingsUpdated);
      socket.on("settings-data", handleSettingsData);
    }

    return () => {
      if (socket) {
        socket.off("settings-updated", handleSettingsUpdated);
        socket.off("settings-data", handleSettingsData);
      }
    };
  }, [socket, roomCode]);

  const handleSettingChange = (key, value) => {
    setTempSettings((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const handleSaveSettings = () => {
    if (socket && roomCode) {
      socket.emit("update-settings", {
        roomCode,
        settings: tempSettings,
      });
      closeSettings();
    }
  };

  const handleCancelSettings = () => {
    setTempSettings(settings);
    closeSettings();
  };

  const openSettings = () => {
    setShowSettings(true);
    requestAnimationFrame(() => setAnimateSettings(true));
  };

  const closeSettings = () => {
    setAnimateSettings(false);
    setTimeout(() => setShowSettings(false), 300);
  };

  const SettingsModal = () => (
    <div
      className={`fixed inset-0 z-50 flex items-center justify-center p-4 bg-blck/40 tranisiton-opacity duration-300 ${animateSettings ? "opacity-100" : "opacity-0"}`}
      onClick={closeSettings}
    >
      <div
        className={`game-panel w-full max-w-md transform transition-all duration-300 ease-out ${animateSettings ? "scale-100 translate-y-0 opacity-100" : "scale-90 translate-y-6 opacity-0"}`}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="p-4 border-b-2 border-game-border flex items-center justify-between shrink-0">
          <h2 className="font-bold text-game-text flex items-center gap-2">
            <Settings className="w-5 h-5" />
            room settings
          </h2>
          <button
            onClick={closeSettings}
            className="p-1 hover:bg-slate-100 rounded-full transition-colors"
          >
            <X className="w-5 h-5 text-slate-600" />
          </button>
        </div>
        <div className="p-4 space-y-4">
          <div>
            <label classname="text-sm font-semibold text-slate-700 mb-2 flex items-center gap-2">
              <Users className="w-4 h-4" /> Maximum Players
            </label>
            <select
              value={tempSettings.maxPlayers}
              onChange={(e) =>
                handleSettingChange("maxPlayers", parseInt(e.target.value))
              }
              className="w-full text-sm px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent focus:outline-none"
            >
              {[4, 5, 6, 7, 8, 9, 10].map((num) => (
                <option key={num} value={num}>
                  {num}players
                </option>
              ))}
            </select>
            <p className="text-xs text-slate-500 mt-1">
              How many players can join the room
            </p>
          </div>
          <div>
            <label className="text-sm font-semibold text-slate-700 mb-2 flex items-center gap-2">
              <Clock className="w-4 h-4" /> Round Duration
            </label>
            <select
              value={tempSettings.roundDuration}
              onChange={(e) =>
                handleSettingChange("roundDuration", parseInt(e.target.value))
              }
              className="w-full text-sm px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent focus:outline-none"
            >
              {[30, 60, 90, 120].map((duration) => (
                <option key={duration} value={duration}>
                  {duration}seconds
                </option>
              ))}
            </select>
            <p className="text-xs text-slate-500 mt-1">
              Time limit for each drawing round.
            </p>
          </div>
          <div>
            <label className="text-sm font-semibold text-slate-700 mb-2 flex items-center gap-2">
              <Trophy className="w-4 h-4" />
              Number of Rounds
            </label>
            <select
              value={tempSettings.maxRounds}
              onChange={(e) =>
                handleSettingChange("maxRounds", parseInt(e.target.value))
              }
              className="w-full text-sm px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent focus:outline-none"
            >
              {[3, 4, 5, 6, 7, 8].map((rounds) => (
                <option key={rounds} value={rounds}>
                  {rounds} rounds
                </option>
              ))}
            </select>
            <p className="text-xs text-slate-500 mt-1">
              Total number of rounds in the game
            </p>
          </div>
          <div>
            <label className="text-sm font-semibold text-slate-700 mb-2 flex items-center gap-2">
              <Zap className="w-4 h-4" />
              Difficulty Level
            </label>
            <select
              value={tempSettings.difficulty}
              onChange={(e) =>
                handleSettingChange("difficulty", e.target.value)
              }
              className="w-full text-sm px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent focus:outline-none"
            >
              <option value="easy">Easy</option>
              <option value="medium">Medium</option>
              <option value="hard">Hard</option>
            </select>
            <p className="text-xs text-slate-500 mt-1">
              Word complexity and challenge level
            </p>
          </div>
        </div>

        <div className="p-4 border-t border-slate-200 flex gap-2">
          <button
            onClick={handleCancelSettings}
            className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors font-medium cursor-pointer text-sm"
          >
            Cancel
          </button>
          <button
            onClick={handleSaveSettings}
            className="game-btn flex-1 px-4 py-2 text-sm"
          >
            Save
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1 p-4 flex flex-col items-center justify-center bg-white min-h-0 overflow-hidden">
        <p className="texxt-center font-bold text-game-text text-md py-2 mb-2">
          ⚙️ room settings
        </p>
        <div className="game-panel px-4 py-6 w-full max-w-md mb-4">
          <div className="space-y-3 text-sm text-game-text">
            <div className="flex items-center justify-between">
              <span className="flex items-center gap-2 font-medium tracking-wide">
                <Users className="w-4 h-4" />
                Max PLayers:
              </span>
              <span className="font-semibold">{settings.maxPlayers}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="flex items-center gap-2 font-medium tracking-wide">
                <Clock className="w-4 h-4" />
                Round Duration:
              </span>
              <span className="font-semibold">{settings.roundDuration} s</span>
            </div>
            <div clasName="flex items-center justify-between">
              <span className="flex items-center gap-2 font-medium tracking-wide">
                <Trophy className="w-4 h-4" /> Total Rounds:
              </span>
              <span className="font-semibold">{settings.maxRounds}</span>
            </div>
            <div className="flex items-center justify-between">
              <span className="flex items-center gap-2 font-medium tracking-wide">
                <Zap className="w-4 h-4" />
                Difficulty:
              </span>
              <span className="font-semibold capitalize">
                {settings.difficulty}
              </span>
            </div>
          </div>
        </div>
        {isHost && (
          <button
            onClick={openSettings}
            className="game-btn-secondary game-btn flex items-center gap-2 px-4 py-2 text-sm"
          >
            <Settings className="w-4 h-4" />
            change settings
          </button>
        )}
        {!isHost && (
          <p className="text-xs text-game-muted mt-2 font-semibold">
            only the host can change settings
          </p>
        )}
      </div>
      {mounted &&
        showSettings &&
        isHost &&
        createPortal(<SettingsModal />, document.body)}
    </div>
  );
};
export default SettingsScreen;
